INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(4031928, 'Change of Heart', '心变', '心変わり', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。'),
(74095602, 'Change of Hero - Reflector Ray', '英雄变化-反光体', '英雄変化－リフレクター・レイ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「元素英雄」的融合怪兽被战斗破坏送去墓地时才能发动。给与对方基本分破坏的融合怪兽等级×300的数值的伤害。'),
(18914778, 'Change Slime', '变形史莱姆', 'チェンジ・スライム', 'Normal Monster', 'Aqua', 'WATER', 1, 400, 300, '能自由地变换形态的史莱姆。'),
(25652655, 'Changer Synchron', '变更同调士', 'チェンジ・シンクロン', 'Tuner Monster', 'Machine', 'DARK', 1, NULL, NULL, '这张卡被同调怪兽的同调召唤使用送去墓地的场合，选择对方场上存在的1只怪兽把表示形式变更。'),
(24673894, 'Changing Destiny', '改变命运', 'チェンジ・デステニー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。把1只对方怪兽的攻击无效，那只怪兽变成守备表示。那只怪兽只要在场上表侧表示存在，变成不能把表示形式变更。那之后，对方从以下效果选择1个适用。 ●自己基本分回复用这张卡的效果把攻击无效的怪兽的攻击力一半的数值。 ●给与对方基本分用这张卡的效果把攻击无效的怪兽的攻击力一半数值的伤害。'),
(76352503, 'Changshi the Spiridao', '灵道士 姜诗', '霊道士チャンシー', 'Effect Monster', 'Zombie', 'DARK', 6, 2000, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡·卡组把1只不死族怪兽送去墓地。 ②：这张卡被除外的场合，从自己墓地把1只不死族怪兽除外才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合回到持有者卡组最下面。'),
(19048328, 'Chaofeng, Phantom of the Yang Zing', '幻龙星－嘲风', '幻竜星－チョウホウ', 'Synchro Monster', 'Wyrm', 'LIGHT', 9, 2800, 2200, '调整＋调整以外的怪兽1只以上 ①：只要同调召唤的这张卡在怪兽区域存在，对方不能把原本属性和作为这张卡的同调素材的「龙星」怪兽相同的怪兽的效果发动。 ②：同调召唤的这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把1只调整加入手卡。 ③：1回合1次，对方场上的怪兽被战斗·效果破坏时才能发动。原本属性和那1只怪兽相同的1只幻龙族怪兽从自己卡组守备表示特殊召唤。'),
(29925614, 'Chaos Allure Queen', '混沌的魅惑女王', '混沌なる魅惑の女王', 'Effect Monster', 'Spellcaster', 'LIGHT', 7, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把1只其他的光·暗属性怪兽丢弃才能发动。这张卡从手卡特殊召唤。 ②：以自己或对方的墓地1只怪兽为对象才能发动。那只怪兽当作装备魔法卡使用给这张卡装备。这张卡直到结束阶段当作和这个效果装备的怪兽同名卡使用。这个效果把光·暗属性的怪兽卡装备的场合，可以再从自己的卡组·墓地把1只暗属性「魅惑的女王」怪兽特殊召唤。'),
(51788412, 'Chaos Ancient Gear Giant', '古代机械齿轮・混沌巨人', '古代の機械混沌巨人', 'Fusion Monster', 'Machine', 'DARK', 10, 4500, 3000, '「古代的机械」怪兽×4 这张卡不用融合召唤不能特殊召唤。 ①：只要这张卡在怪兽区域存在，这张卡不受魔法·陷阱卡的效果影响，对方在战斗阶段中不能把怪兽的效果发动。 ②：这张卡可以向对方怪兽全部各作1次攻击，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(22850702, 'Chaos Angel', '混沌天使－混元的双翼－', 'カオス・アンヘル－混沌の双翼－', 'Synchro Monster', 'Fiend', 'DARK', 10, 3500, 2800, '调整＋调整以外的光·暗属性怪兽1只以上 这张卡同调召唤的场合，可以把自己场上1只光·暗属性怪兽当作调整使用。 ①：这张卡特殊召唤的场合，以场上1张卡为对象才能发动。那张卡除外。 ②：这张卡得到作为这张卡的同调素材的怪兽的原本属性的以下效果。 ●光：自己场上的同调怪兽不受对方发动的怪兽的效果影响。 ●暗：自己怪兽不会被战斗破坏。'),
(13076804, 'Chaos Archfiend', '混沌恶魔－混元的魔神－', 'カオス・デーモン－混沌の魔神－', 'Synchro Monster', 'Fiend', 'DARK', 8, 2500, 1800, '光属性调整＋调整以外的暗属性怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这个回合是已有卡被除外的场合，这张卡的攻击力上升2000。 ②：这张卡可以向对方怪兽全部各作1次攻击，这张卡战斗破坏的怪兽不去墓地而除外。 ③：这张卡因对方从场上离开的场合才能发动。「混沌之魔神」以外的1只「混沌」同调怪兽从额外卡组特殊召唤。'),
(49565413, 'Chaos Beast', '混沌猛兽－混元的魔兽－', 'カオス・ビースト－混沌の魔獣－', 'Synchro Monster', 'Fiend', 'DARK', 6, 2000, 1800, '光属性调整＋调整以外的暗属性怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：这个回合是已有卡被除外的场合，这张卡的攻击力上升1000。 ②：以除外的1只自己的光·暗属性怪兽为对象才能发动。那只怪兽加入手卡。 ③：把这张卡以外的光·暗属性怪兽各1只从自己的手卡·墓地除外才能发动。这张卡从墓地特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(34966096, 'Chaos Betrayer', '混沌叛徒', 'カオス・ベトレイヤー', 'Effect Monster', 'Fiend', 'DARK', 6, 2000, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，从自己墓地把「混沌叛徒」以外的光属性和暗属性的怪兽各1只除外才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡特殊召唤成功的场合，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(4923662, 'Chaos Burst', '混沌炸裂', 'カオス・バースト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时把自己场上1只怪兽解放，以那1只攻击怪兽为对象才能发动。那只攻击怪兽破坏。那之后，给与对方1000伤害。'),
(72630549, 'Chaos Command Magician', '混沌魔导师', 'カオス・マジシャン', 'Effect Monster', 'Spellcaster', 'LIGHT', 6, 2400, 1900, '①：只要这张卡在怪兽区域存在，只以这1张卡为对象的怪兽的效果无效化。'),
(54040484, 'Chaos Core', '混沌核心', 'カオス・コア', 'Effect Monster', 'Fiend', 'DARK', 3, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡成为效果的对象时或者被选择作为对方怪兽的攻击对象时才能发动。「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」各最多1只从手卡·卡组送去墓地，送去墓地数量的幻魔指示物给这张卡放置，这个回合自己受到的战斗伤害变成0。 ②：这张卡被战斗·效果破坏的场合，可以作为代替把这张卡1个幻魔指示物取除。'),
(26873574, 'Chaos Daedalus', '混沌代达罗斯', 'カオス・ダイダロス', 'Effect Monster', 'Sea Serpent', 'DARK', 7, 2600, 1500, '这张卡不能通常召唤。从自己墓地把光属性和暗属性的怪兽各1只除外的场合可以特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：只要场地魔法卡表侧表示存在，自己场上的光·暗属性怪兽不会成为对方的效果的对象。 ②：场地魔法卡表侧表示存在的场合，以最多有那个数量的场上的卡为对象才能发动。那些卡除外。'),
(6500778, 'Chaos Distill', '炼金釜－混沌蒸馏', '錬金釜－カオス・ディスティル', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，被送去自己墓地的卡不去墓地而除外。 ②：可以从以下效果选择1个发动。 ●除「炼金釜-混沌蒸馏釜」外的1张「大宇宙」或者有那个卡名记述的卡从卡组加入手卡。 ●场上有「大宇宙」存在的场合，把魔法与陷阱区域的表侧表示的这张卡除外才能发动。从卡组把1只攻击力?的光属性怪兽加入手卡。'),
(55878038, 'Chaos Dragon Levianeer', '混源龙利维奥尼亚', '混源龍レヴィオニア', 'Effect Monster', 'Dragon', 'DARK', 8, 3000, NULL, '这张卡不能通常召唤。从自己墓地把光·暗属性怪兽合计3只除外的场合可以特殊召唤。这个卡名的效果1回合只能使用1次。 ①：这个方法让这张卡特殊召唤成功时才能发动。为那次特殊召唤而除外的怪兽属性的以下效果适用。这个回合，这张卡不能攻击。 ●只有光：从自己墓地选1只怪兽守备表示特殊召唤。 ●只有暗：对方手卡随机选1张回到卡组。 ●光和暗：选场上最多2张卡破坏。'),
(82301904, 'Chaos Emperor Dragon - Envoy of the End', '混沌帝龙 －终焉的使者－', '混沌帝龍 －終焉の使者－', 'Effect Monster', 'Dragon', 'DARK', 8, 3000, 2500, '这张卡不能通常召唤。从自己墓地把光·暗属性怪兽各1只除外的场合才能特殊召唤。这张卡的效果发动的回合，自己不能把其他的效果发动。 ①：1回合1次，支付1000基本分才能发动。双方的手卡·场上的卡全部送去墓地。那之后，给与对方这个效果送去对方墓地的卡数量×300伤害。'),
(4538826, 'Chaos Emperor, the Dragon of Armageddon', '终焉龙 混沌帝', '終焉龍 カオス・エンペラー', 'Pendulum Effect Monster', 'Dragon', 'DARK', 8, 3000, 2500, '这张卡不能通常召唤。「终焉龙 混沌帝」1回合1次在把自己墓地的光属性和暗属性的怪兽各1只除外的场合才能从手卡·额外卡组特殊召唤。 ①：1回合1次，把基本分支付一半才能发动。额外怪兽区域以外的自己场上的卡全部送去墓地，选最多有送去墓地的数量的对方场上的卡送去墓地。那之后，给与对方送去对方墓地的数量×300伤害。 ②：特殊召唤的表侧表示的这张卡从场上离开的场合回到卡组最下面。'),
(61044390, 'Chaos End', '混沌终结', 'カオス・エンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '当自己的卡有7张以上被除外时这张卡才能发动。破坏场上存在的所有怪兽卡。'),
(21082832, 'Chaos Form', '混沌形态', 'カオス・フォーム', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '①：等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放或者作为解放的代替而从自己墓地把「青眼白龙」或「黑魔术师」除外，从手卡把1只「混沌」仪式怪兽仪式召唤。'),
(31385077, 'Chaos Goddess', '混沌神女－混元的女神－', 'カオス・ゴッデス－混沌の女神－', 'Synchro Monster', 'Fairy', 'LIGHT', 8, 2500, 1800, '光属性调整＋调整以外的暗属性怪兽2只以上 ①：1回合1次，从手卡把1只光属性怪兽送去墓地，以自己墓地1只5星以上的暗属性怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽不能作为同调素材。'),
(97439308, 'Chaos Greed', '混沌贪欲', 'カオス・グリード', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '当自己的卡有4张以上从游戏中除外，且自己的墓地里没有卡存在时这张卡才能发动。从自己的卡组抽2张卡。'),
(18859369, 'Chaos Grepher', '混沌斗士 格雷法', 'カオス・グレファー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, 1600, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，这张卡的属性也当作「暗」使用。 ②：从手卡丢弃1只光属性或者暗属性的怪兽才能发动。和丢弃的怪兽属性不同的1只光·暗属性怪兽从卡组送去墓地。这个回合，自己不能把这个效果送去墓地的怪兽以及那些同名怪兽特殊召唤。'),
(97940434, 'Chaos Hunter', '混沌猎人', 'カオスハンター', 'Effect Monster', 'Fiend', 'DARK', 7, 2500, 1600, '①：对方对怪兽的特殊召唤成功时，把这张卡以外的1张手卡丢弃才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，对方不能把卡除外。'),
(4081825, 'Chaos Infinity', '混沌无限', 'カオス・インフィニティ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的守备表示怪兽全部变成表侧攻击表示。那之后，从自己的卡组·墓地选1只「机皇」怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。'),
(36407615, 'Chaos King Archfiend', '恶魔混沌王', 'デーモン・カオス・キング', 'Synchro Monster', 'Fiend', 'DARK', 7, 2600, 2600, '恶魔族调整＋调整以外的怪兽1只以上 这张卡的攻击宣言时，可以让对方场上表侧表示存在的全部怪兽的攻击力·守备力直到战斗阶段结束时交换。'),
(66699781, 'Chaos Mirage Dragon', '混沌幻象龙', 'カオス・ミラージュ・ドラゴン', 'Tuner Monster', 'Wyrm', 'LIGHT', 4, 1600, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：以除外的1只自己或者对方的光·暗属性怪兽为对象才能发动。那只怪兽效果无效在自己场上特殊召唤。这个效果的发动后，直到回合结束时自己不是光·暗属性的同调怪兽不能从额外卡组特殊召唤。 ②：这张卡作为同调素材送去墓地的场合，以最多有作为那次同调召唤的素材的除这张卡以外的怪兽数量的对方场上的卡为对象才能发动。那些卡除外。'),
(1434352, 'Chaos Necromancer', '混沌死灵师', 'カオス・ネクロマンサー', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这张卡的攻击力为自己墓地里存在的怪兽卡数量×300点的数值。'),
(24226942, 'Chaos Nephthys', '混沌奈芙蒂斯', 'カオス・ネフティス', 'Effect Monster', 'Winged Beast', 'DARK', 8, 2400, 1600, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，场上的卡被效果破坏的场合，从自己墓地把「混沌奈芙提斯」以外的光属性和暗属性的怪兽各1只除外才能发动。这张卡特殊召唤。 ②：这张卡特殊召唤成功的场合，以对方场上1张卡和对方墓地2张卡为对象才能发动。那些卡除外。'),
(60329973, 'Chaos Phantasm', '混沌变幻', '混沌変幻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以除外的自己的光属性调整和调整以外的8星以下的暗属性怪兽各1只为对象才能发动。那2只怪兽回到墓地。那之后，把持有和回去的怪兽的等级合计相同等级的1只光·暗属性同调怪兽从额外卡组特殊召唤。'),
(3040496, 'Chaos Ruler, the Chaotic Magical Dragon', '混元魔龙 混沌支配者', '混沌魔龍 カオス・ルーラー', 'Synchro Monster', 'Dragon', 'DARK', 8, 3000, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤成功的场合才能发动。从自己卡组上面把5张卡翻开。可以从那之中选1只光·暗属性怪兽加入手卡。剩下的卡送去墓地。 ②：把这张卡以外的光·暗属性怪兽各1只从自己的手卡·墓地除外才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(15256925, 'Chaos Scepter Blast', '毁灭咒文-死亡终极咒', '滅びの呪文－デス・アルテマ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上有8星以上的魔法师族怪兽存在的场合才能发动。选场上1张卡里侧表示除外。 ②：魔法与陷阱区域的这张卡被对方的效果破坏的场合才能发动。从卡组把1只「黑混沌之魔术师」或者「混沌之黑魔术师」无视召唤条件特殊召唤。'),
(76766706, 'Chaos Seed', '混沌之种', '混沌の種', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有光属性以及暗属性怪兽存在的场合，选择除外的1只自己的光属性或者暗属性的战士族怪兽才能发动。选择的怪兽加入手卡。「混沌之种」在1回合只能发动1张。'),
(9596126, 'Chaos Sorcerer', '混沌巫师', 'カオス・ソーサラー', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2300, 2000, '这张卡不能通常召唤。从自己墓地把光·暗属性怪兽各1只除外的场合可以特殊召唤。 ①：1回合1次，以场上1只表侧表示怪兽为对象才能发动（这个效果发动的回合，这张卡不能攻击）。那只表侧表示怪兽除外。'),
(99266988, 'Chaos Space', '混沌领域', '混沌領域', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把1只光·暗属性怪兽送去墓地才能发动。和那只怪兽属性不同并是4～8星的1只不能通常召唤的光·暗属性怪兽从卡组加入手卡。 ②：把墓地的这张卡除外，从除外的自己怪兽之中以1只不能通常召唤的光·暗属性怪兽为对象才能发动。那只怪兽回到卡组最下面。那之后，自己从卡组抽1张。'),
(27439792, 'Chaos Summoning Beast', '混沌召唤神', '混沌の召喚神', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」的其中1只从手卡无视召唤条件特殊召唤。 ②：把墓地的这张卡除外才能发动。从卡组把1张「失乐园」加入手卡。'),
(11593137, 'Chaos Trap Hole', '混沌落穴', '混沌の落とし穴', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '支付2000基本分发动。光属性以及暗属性怪兽的召唤·反转召唤·特殊召唤无效并从游戏中除外。'),
(53871273, 'Chaos Valkyria', '混沌女武神', '混沌のヴァルキリア', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 1050, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：从自己墓地把1只光属性或者暗属性的怪兽除外才能发动。这张卡从手卡特殊召唤。 ②：这张卡被除外的场合才能发动。从卡组把1只光属性或者暗属性的怪兽送去墓地。这个回合，自己不能把这个效果送去墓地的卡以及那些同名卡的效果发动。'),
(30327674, 'Chaos Witch', '混沌女巫－混元的魔女－', 'カオス・ウィッチ－混沌の魔女－', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1500, '这个卡名的①②的效果1回合只能有1次使用其中任意1个，发动的回合，自己不是光·暗属性的同调怪兽不能从额外卡组特殊召唤。 ①：把这张卡解放才能发动。在自己场上把2只「黑兽衍生物」（恶魔族·暗·2星·攻1000/守500）特殊召唤。 ②：这张卡从手卡·墓地除外的场合才能发动。在自己场上把2只「白兽衍生物」（天使族·调整·光·2星·攻500/守1000）特殊召唤。'),
(94243005, 'Chaos Zone', '混沌空间', '混沌空間', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：每次怪兽被表侧表示除外，每有1只给这张卡放置1个混沌指示物。 ②：1回合1次，把自己场上的混沌指示物4个以上取除，以持有和取除数量相同等级的除外的1只自己或者对方的怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。 ③：场上的这张卡被对方的效果送去墓地时才能发动。把持有这张卡放置的混沌指示物数量以下的等级的1只光·暗属性的怪兽从卡组加入手卡。'),
(46609443, 'Chaos-End Master', '混沌终结王', 'カオスエンドマスター', 'Tuner Monster', 'Warrior', 'LIGHT', 3, 1500, 1000, '这张卡战斗破坏对方怪兽送去墓地时，可以从卡组把1只5星以上而攻击力1600以下的怪兽特殊召唤。'),
(47829960, 'Chaosrider Gustaph', '混沌骑手 古斯塔夫', 'カオスライダー グスタフ', 'Effect Monster', 'Warrior', 'WIND', 4, 1400, 1500, '从自己墓地里除外至多2张魔法卡。以此效果每除外1张卡，这张卡的攻击力就上升300点直到对方回合结束。此效果1回合只能使用1次。'),
(92221402, 'Chaotic Elements', '混沌元素', 'カオティック・エレメンツ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的卡组·墓地把1只5星以上而炎族·水族的光·暗属性怪兽加入手卡。那之后，自己墓地有炎族·水族怪兽3只以上存在的场合，可以把场上1张卡破坏。 ②：对方场上有炎族·水族的光·暗属性怪兽存在的场合，把墓地的这张卡除外，以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。'),
(13179332, 'Charcoal Inpachi', '大木炭18', '大木炭１８', 'Normal Monster', 'Pyro', 'FIRE', 1, 100, 2100, '完全燃烧殆尽的巨木之化身。用此炭烤出的肉被公认为极品而受到珍重。'),
(85325774, 'Charge Into a Dark World', '暗黑界的援军', '暗黒界の援軍', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只4星以下的恶魔族怪兽为对象才能发动。那只怪兽特殊召唤。那之后，从手卡选1只恶魔族怪兽丢弃。'),
(94886282, 'Charge of the Light Brigade', '光之援军', '光の援軍', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己卡组上面把3张卡送去墓地才能发动。从卡组把1只4星以下的「光道」怪兽加入手卡。'),
(84482694, 'Charged-Up Heraldry', '显现的徽章', '顕現する紋章', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只怪兽解放才能发动。从卡组把2只「纹章兽」怪兽守备表示特殊召唤。这张卡的发动后，直到回合结束时自己不是念动力族怪兽以及机械族怪兽不能从额外卡组特殊召唤。'),
(7841921, 'Charging Gaia the Fierce Knight', '疾走暗黑骑士盖亚', '疾走の暗黒騎士ガイア', 'Effect Monster', 'Warrior', 'LIGHT', 7, 2300, 2100, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡可以不用解放作召唤。 ②：不用解放作召唤的这张卡的原本攻击力变成1900。 ③：这张卡被解放的场合才能发动。从卡组把1只「混沌战士」怪兽加入手卡。'),
(49191560, 'Charioteer of Prophecy', '魔导剑士 沙里奥', '魔導剣士 シャリオ', 'Effect Monster', 'Spellcaster', 'WIND', 4, 1800, 1300, '1回合1次，从手卡丢弃1张名字带有「魔导书」的魔法卡才能发动。选择自己墓地1只魔法师族怪兽加入手卡。'),
(50412166, 'Charm of Shabti', '沙布提俑护符', 'シャブティのお守り', 'Effect Monster', 'Rock', 'EARTH', 1, 100, 100, '从手卡丢弃这张卡。到本回合结束阶段为止，自己场上名称中带有「守墓」的怪兽卡所受战斗伤害为0。'),
(48016074, 'Charmers of the Grand Circle', '大轮之灵使', '大輪の霊使い', 'Fusion Monster', 'Spellcaster', 'LIGHT', 6, 1850, 1500, '「灵使」、「凭依装着」怪兽×2只以上 这个卡名的效果1回合只能使用1次。 ①：这张卡融合召唤的场合才能发动。让最多有作为这张卡的融合素材的怪兽的原本属性种类数量的「从以下效果选1个，那个效果适用」处理重复（最多4次）。 ●这张卡的攻击力上升800。 ●从卡组把1张「凭依」魔法·陷阱卡加入手卡。 ●场上1张卡回到手卡。 ●从自己墓地把1只魔法师族怪兽特殊召唤。'),
(64753157, 'Charming Resort Staff', '“度假胜地”店员－可人儿', '「RESORT」 STAFF－チャーミング', 'Effect Monster', 'Fairy', 'LIGHT', 3, 300, 200, '①：自己的「秘旋谍-花公子」和对方的表侧表示怪兽进行战斗的攻击宣言时才能发动。那只对方怪兽的攻击力变成0。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把1只「秘旋谍-花公子」特殊召唤。 ③：这张卡在墓地存在，自己场上的表侧表示的「秘旋谍-花公子」被战斗破坏的场合或者被送去墓地的场合，把墓地的这张卡除外才能发动。选自己墓地1只「秘旋谍-花公子」加入手卡。'),
(37421579, 'Charubin the Fire Knight', '炎之骑士 基拉', '炎の騎士 キラー', 'Fusion Monster', 'Pyro', 'FIRE', 3, 1100, 800, '「怪兽蛋」＋「史汀」'),
(4965193, 'Chasma, Dragon Ruler of Auroras', '极征龙－天裂', '極征竜－シャスマティス', 'XYZ Monster', 'Dragon', 'LIGHT', 7, 3000, 1600, '龙族7星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，从卡组把1只7星「征龙」怪兽送去墓地，把这张卡1个超量素材取除才能发动。这个效果变成和从卡组送去墓地的那只怪兽的把自身从手卡丢弃发动的效果相同。 ②：这张卡被战斗或者对方的效果破坏的场合才能发动。自己的墓地·除外状态的1只7星「征龙」怪兽特殊召唤。'),
(69313735, 'Checkmate', '闪击', 'ディスカバード・アタック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '祭掉自己场上1只名称中含有「恶魔」字样的怪兽。本回合，自己场上的1只「灭绝国王恶魔」可以对对方进行直接攻击。'),
(94136469, 'Checksum Dragon', '校验和龙', 'チェックサム・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 6, 400, 2400, '①：对方怪兽的攻击宣言时才能发动。这张卡从手卡特殊召唤。那之后，自己基本分回复这张卡的守备力一半的数值。 ②：攻击表示的这张卡不会被战斗破坏。'),
(27189308, 'Cheepcheepcheep', '喔喔雏鸡', 'ぴよコッコ', 'Effect Monster', 'Winged Beast', 'WIND', 1, 300, 200, '反转：可以从卡组把1只5星以上的调整特殊召唤。'),
(29251488, 'Chef de Nouvelles', '主厨・饿魔新飨', 'シェフ・ド・ヌーベルズ', 'Pendulum Effect Monster', 'Fiend', 'LIGHT', 3, 1000, 1850, '这个卡名的①②的怪兽效果在同一连锁上不能发动。 ①：自己·对方回合1次，以场上1只效果怪兽为对象才能发动。那只怪兽的等级上升最多3星。 ②：1回合1次，对方把怪兽特殊召唤的场合，从自己的手卡·卡组·墓地把1张「食谱」仪式魔法卡除外才能发动。那张仪式魔法卡发动时的仪式召唤效果适用。 ③：场上的这张卡被解放以表侧加入额外卡组的场合才能发动。这张卡在自己的灵摆区域放置。'),
(87955518, 'Chef''s Special Recipe', 'Recette de Spécialité～主厨的看家食谱～', 'Recette de Spécialité～料理長自慢のレシピ～', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「新式魔厨」仪式怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效。「新式魔厨」怪兽的效果特殊召唤的怪兽在自己场上存在的场合，可以再把那张无效的卡破坏。 ②：自己对「饥饿的汉堡」的特殊召唤成功的场合，把墓地的这张卡除外才能发动。对方场上的怪兽尽可能解放。'),
(81599449, 'Chemicritter Carbo Crab', '化合兽 碳素蟹', '化合獣カーボン・クラブ', 'Gemini Monster', 'Aqua', 'FIRE', 2, 700, 1400, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●自己主要阶段才能发动。从卡组把1只二重怪兽送去墓地。那之后，从卡组把1只二重怪兽加入手卡。这个卡名的这个效果1回合只能使用1次。'),
(55100740, 'Chemicritter Hydron Hawk', '化合兽 氢素鹰', '化合獣ハイドロン・ホーク', 'Gemini Monster', 'Winged Beast', 'WATER', 2, 1400, 700, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●丢弃1张手卡，以自己墓地1只二重怪兽为对象才能发动。那只怪兽守备表示特殊召唤。「化合兽 氢素鹰」的这个效果1回合只能使用1次。'),
(18993198, 'Chemicritter Oxy Ox', '化合兽 氧素牛', '化合獣オキシン・オックス', 'Gemini Monster', 'Beast', 'WIND', 2, NULL, 2100, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●自己主要阶段才能发动。从手卡把1只二重怪兽特殊召唤，自己场上的全部二重怪兽的等级直到回合结束时变成和这个效果特殊召唤的怪兽的原本等级相同。「化合兽 氧素牛」的这个效果1回合只能使用1次。'),
(300302046, 'Chemistry in Motion', NULL, NULL, 'Skill Card', 'Bastion Misaw', NULL, NULL, NULL, NULL, NULL),
(525110, 'Cherry Inmato', '迷你番茄小子', 'プチトマボー', 'Tuner Monster', 'Plant', 'DARK', 2, 700, 400, '这张卡被战斗破坏送去墓地时，可以从自己卡组把最多2只名字带有「番茄小子」的怪兽特殊召唤。这个效果特殊召唤的怪兽这个回合不能作为同调素材。'),
(64626565, 'Cherubidamn Irisfiel', NULL, NULL, 'XYZ Monster', 'Fairy', 'LIGHT', 8, 800, 2500, NULL),
(58699500, 'Cherubini, Ebon Angel of the Burning Abyss', '彼岸之黑天使 凯鲁比尼', '彼岸の黒天使 ケルビーニ', 'Link Monster', 'Fairy', 'DARK', NULL, 500, NULL, '3星怪兽2只 这个卡名的③的效果1回合只能使用1次。 ①：这张卡所连接区的怪兽不会被效果破坏。 ②：场上的这张卡被战斗或者对方的效果破坏的场合，可以作为代替把自己场上1张卡送去墓地。 ③：从卡组把1只3星怪兽送去墓地，以场上1只「彼岸」怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升送去墓地的怪兽的各自数值。'),
(45037489, 'Chevalier de Fleur', '鲜花之骑士', 'フルール・ド・シュヴァリエ', 'Synchro Monster', 'Warrior', 'WIND', 8, 2700, 2300, '「鲜花同调士」＋调整以外的怪兽1只以上 ①：1回合1次，自己回合对方把魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(13023431, 'Chevreuil, Hunting Scout of the Deep Forest', '深林狩哨 獐鹿', NULL, 'Fusion Monster', 'Warrior', 'EARTH', 7, 2600, 2600, '5星以上的战士族·地属性怪兽+战士族·地属性怪兽 这张卡在主要阶段期间不受对方发动的效果影响。 可以攻击的对方怪兽必须向自己场上攻击力最高的怪兽作出攻击。 自己场上的其他战士族·地属性怪兽战斗破坏对方怪兽时：可以把自己墓地·除外状态的1只战士族·地属性怪兽特殊召唤。「深林狩哨 獐鹿」的这个效果1回合只能使用1次。'),
(7392745, 'Chewbone', '鼠骨', 'チュウボーン', 'Flip Effect Monster', 'Zombie', 'EARTH', 3, 300, 300, '①：这张卡反转的场合发动。在对方场上把3只「小鼠骨衍生物」（不死族·地·1星·攻100/守300）守备表示特殊召唤。'),
(7392746, 'Chewbone Jr. Token', '鼠骨', 'チュウボーン', 'Token', 'Zombie', NULL, NULL, NULL, NULL, NULL),
(67616300, 'Chicken Game', '试胆竞速', 'チキンレース', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，比对方基本分少的玩家受到的全部伤害变成0。 ②：双方玩家1回合1次，自己主要阶段可以支付1000基本分从以下效果选择1个发动。双方不能对应这个效果的发动把魔法·陷阱·怪兽的效果发动。 ●从卡组抽1张。 ●这张卡破坏。 ●对方回复1000基本分。'),
(12021072, 'Child''s Play', '大胆无敌', '大胆無敵', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次对方把怪兽召唤·反转召唤·特殊召唤，自己回复300基本分。 ②：自己基本分是10000以上的场合，自己怪兽不会被战斗破坏。'),
(300302047, 'Chillin'' Outback', NULL, NULL, 'Skill Card', 'Chumley Huffi', NULL, NULL, NULL, NULL, NULL),
(501000006, 'Chimaera, the Master of Beasts', NULL, NULL, 'Effect Monster', 'Beast', 'LIGHT', 9, 3000, 3000, NULL),
(63136489, 'Chimera Fusion', '客迈拉结合', '合成獣融合', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己·对方的主要阶段才能发动。包含兽族·恶魔族怪兽其中任意种的自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。 ②：自己主要阶段有这张卡在墓地存在，自己的场上或墓地有「有翼幻兽 奇美拉」存在的场合，可以从以下选择1个发动。 ●这张卡加入手卡。 ●这张卡除外，从自己的卡组·墓地把1只「幻兽王 加泽尔」和1只「巴风特」特殊召唤。'),
(4796100, 'Chimera the Flying Mythical Beast', '有翼幻兽 客迈拉', '有翼幻獣キマイラ', 'Fusion Monster', 'Beast', 'WIND', 6, 2100, 1800, '「幻兽王 加泽尔」＋「巴风特」 ①：这张卡被破坏时，以自己墓地1只「幻兽王 加泽尔」或「巴风特」为对象才能发动。那只怪兽特殊召唤。'),
(38264974, 'Chimera the Illusion Beast', '幻想魔兽 客迈拉', '幻想魔獣キマイラ', 'Fusion Monster', 'Illusion', 'DARK', 8, 3100, 2800, '「有翼幻兽 奇美拉」＋幻想魔族怪兽1只以上 ①：这张卡的卡名只要在场上·墓地存在当作「有翼幻兽 奇美拉」使用。 ②：这张卡在同1次的战斗阶段中可以向怪兽作出最多有作为这张卡的融合素材的怪兽数量的攻击。 ③：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ④：这张卡和对方怪兽进行战斗的伤害步骤结束时才能发动。那只对方怪兽的攻击力变成0，效果无效化。'),
(1769875, 'Chimera the King of Phantom Beasts', '幻兽王 客迈拉', '幻獣王キマイラ', 'Fusion Monster', 'Beast', 'WIND', 6, 2100, 1800, '兽族怪兽＋恶魔族怪兽 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「有翼幻兽 奇美拉」使用。 ②：这张卡融合召唤的场合才能发动。这个回合的结束阶段把对方手卡随机1张送去墓地。 ③：对方回合把墓地的这张卡除外，以自己墓地1只兽族·恶魔族·幻想魔族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(79229522, 'Chimeratech Fortress Dragon', '嵌合要塞龙', 'キメラテック・フォートレス・ドラゴン', 'Fusion Monster', 'Machine', 'DARK', 8, NULL, NULL, '「电子龙」＋机械族怪兽1只以上 把自己·对方场上的上记的卡送去墓地的场合才能从额外卡组特殊召唤。这张卡不能作为融合素材。 ①：这张卡的原本攻击力变成作为这张卡的融合素材的怪兽数量×1000。'),
(87116928, 'Chimeratech Megafleet Dragon', '嵌合巨舰龙', 'キメラテック・メガフリート・ドラゴン', 'Fusion Monster', 'Machine', 'DARK', 10, NULL, NULL, '「电子龙」怪兽＋额外怪兽区域的怪兽1只以上 把自己·对方场上的上记的卡送去墓地的场合才能从额外卡组特殊召唤。这张卡不能作为融合素材。 ①：这张卡的原本攻击力变成作为这张卡的融合素材的怪兽数量×1200。'),
(64599569, 'Chimeratech Overdragon', '嵌合超载龙', 'キメラテック・オーバー・ドラゴン', 'Fusion Monster', 'Machine', 'DARK', 9, -1, -1, '「电子龙」＋机械族怪兽1只以上 这张卡不用融合召唤不能特殊召唤。 ①：这张卡融合召唤的场合发动。自己场上的其他卡全部送去墓地。 ②：这张卡的原本的攻击力·守备力变成作为这张卡的融合素材的怪兽数量×800。 ③：这张卡在同1次的战斗阶段中可以向怪兽作出最多有作为这张卡的融合素材的怪兽数量的攻击。'),
(84058253, 'Chimeratech Rampage Dragon', '嵌合暴走龙', 'キメラテック・ランページ・ドラゴン', 'Fusion Monster', 'Machine', 'DARK', 5, 2100, 1600, '「电子龙」怪兽×2只以上 这张卡的融合召唤不用上记的卡不能进行。 ①：这张卡融合召唤时，以最多有作为这张卡的融合素材的怪兽数量的场上的魔法·陷阱卡为对象才能发动。那些卡破坏。 ②：1回合1次，自己主要阶段才能发动。从卡组把最多2只机械族·光属性怪兽送去墓地。这个回合，这张卡在同1次的战斗阶段中在通常攻击外加上可以作出最多有这个效果送去墓地的怪兽数量的攻击。'),
(16956455, 'Chiron the Mage', '贤者 喀戎', '賢者ケイローン', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1800, 1000, '从手卡丢弃1张魔法卡。对方场上的1张魔法·陷阱卡破坏。这个效果1回合只能使用1次。'),
(87294988, 'Chirubimé, Princess of Autumn Leaves', '红姬 知流姬', '紅姫チルビメ', 'Effect Monster', 'Plant', 'EARTH', 8, 1800, 2800, '只要这张卡在场上表侧表示存在，对方不能选择其他的植物族怪兽作为攻击对象。此外，这张卡被对方送去墓地的场合，可以从卡组把「红姬 知流姬」以外的1只植物族怪兽特殊召唤。'),
(56532632, 'Chivalry', '威风堂堂', '威風堂々', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '战斗阶段中才能发动。对方发动的效果怪兽的效果无效并破坏。'),
(61488417, 'Chiwen, Light of the Yang Zing', '光龙星－螭吻', '光竜星－リフン', 'Tuner Monster', 'Wyrm', 'LIGHT', 1, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上的这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把「光龙星-螭吻」以外的1只「龙星」怪兽特殊召唤。 ②：这张卡在墓地存在，自己场上的「龙星」怪兽被战斗·效果破坏送去墓地时才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(27352108, 'Chobham Armor Dragon', '乔巴姆装甲龙', 'チョバムアーマー・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 1, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡攻击表示特殊召唤。这个回合，这个效果特殊召唤的这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成一半。 ②：这张卡作为连接素材送去墓地的场合，以这张卡以外的自己墓地1只暗属性怪兽为对象才能发动。那只怪兽加入手卡。对方可以选自身墓地1只怪兽加入手卡。'),
(7198399, 'Chocolate Magician Girl', '巧克力魔术少女', 'チョコ・マジシャン・ガール', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1600, 1000, '①：1回合1次，从手卡丢弃1只魔法师族怪兽才能发动。自己从卡组抽1张。 ②：1回合1次，这张卡被选择作为攻击对象的场合，以「巧克力魔术少女」以外的自己墓地1只魔法师族怪兽为对象才能发动。那只怪兽特殊召唤。那之后，攻击对象转移为那只怪兽，攻击怪兽的攻击力变成一半。'),
(90027012, 'Choju of the Trillion Hands', '兆手之神', 'チョウジュ・ゴッド', 'Effect Monster', 'Fairy', 'LIGHT', 6, 1400, 1000, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合才能发动。从卡组把1只仪式怪兽和1张仪式魔法卡加入手卡。'),
(40884383, 'Chopman the Desperate Outlaw', '凶恶犯-开膛手', '凶悪犯－チョップマン', 'Effect Monster', 'Zombie', 'DARK', 3, 1100, 500, '这张卡反转召唤成功时，可以从自己墓地里选择1张装备魔法卡装备在这张卡身上。'),
(81380218, 'Chorus of Sanctuary', '圣域歌声', '聖域の歌声', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部守备表示的怪兽守备力上升500。'),
(22916281, 'Chosen by the World Chalice', '被星杯选中者', '星杯に選ばれし者', 'Normal Monster', 'Psychic', 'FIRE', 3, 1600, NULL, '以机怪残骸为武装，为人心地正直的少年。 对星辰之森自古流传的『星之勇者』心怀憧憬，答应妖精莉丝的请求，和被授予光芒的同伴们一起踏上了将七件星遗物解放的旅程。 “星光之勇者 举剑汇聚光明 斩除巨大黑暗”'),
(98076754, 'Chosen of Zefra', '神数的圣选士', 'セフィラの聖選士', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：得到自己的额外卡组的表侧表示的「神数」怪兽种类的以下效果。 ●3种类以上：自己场上的怪兽的攻击力上升双方的额外卡组的表侧表示的卡数量×100。 ●5种类以上：自己场上的怪兽不会被对方的效果破坏。 ●8种类以上：自己场上的怪兽不会成为对方的效果的对象。 ●10种类：把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。对方的手卡·场上·墓地的卡全部回到持有者卡组。'),
(21888494, 'Chosen One', '被选中者', '選ばれし者', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选1张自己的手卡的怪兽卡和怪兽以外的种类2张卡。对方在这之中随机选1张，如果选中怪兽卡的场合场上特殊召唤，其他的2张卡送去墓地。选不中的话，全部送去墓地。'),
(99902789, 'Chow Chow Chan', '纠错小松狮', 'チャウチャウちゃん', 'Effect Monster', 'Beast', 'EARTH', 2, 800, 800, '和对方怪兽进行战斗的自己怪兽的攻击宣言时对方把通常陷阱卡发动时，把这张卡从手卡丢弃才能发动。那个发动无效并破坏。'),
(95905259, 'Chow Len the Prophet', '预言僧 长莲', '予言僧 チョウレン', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 1800, 200, '①：1回合1次，宣言卡的种类（魔法·陷阱），以对方的魔法与陷阱区域盖放的1张卡为对象才能发动。那张盖放的卡给双方确认，宣言的种类的场合，这个回合那张卡不能发动。'),
(38412161, 'Chow Sai the Ghost Stopper', '灵塞术师 澄最', '霊塞術師 チョウサイ', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1900, 800, '①：只要这张卡在怪兽区域存在，双方不能把墓地的魔法·陷阱卡的效果发动。 ②：这张卡从场上送去墓地的场合，以对方墓地1张魔法·陷阱卡为对象才能发动。那张卡除外。'),
(60948488, 'Chronicle Magician', '年代记魔术师', 'クロニクル・マジシャン', 'Effect Monster', 'Spellcaster', 'DARK', 7, 2500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有原本攻击力或者原本守备力是2500的怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：这张卡特殊召唤成功的场合，以自己场上1只「黑魔术师」或者「青眼白龙」为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升2500。'),
(54878729, 'Chronicle Sorceress', '年代记女巫', 'クロニクル・ソーサレス', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1250, 1250, '这个卡名的效果1回合只能使用1次。 ①：可以从自己墓地的怪兽属性的以下效果选择1个发动。 ●光：除「年代记女巫」外的1只「青眼白龙」或者1张有那个卡名记述的卡从卡组送去墓地。 ●暗：除「年代记女巫」外的1只「黑魔术师」或者1张有那个卡名记述的卡从卡组送去墓地。'),
(4026187, 'Chronicler of Fairy Tail Tales', NULL, NULL, 'Fusion Monster', 'Spellcaster', 'EARTH', 4, 1850, 1000, NULL),
(25397880, 'Chronicler of Nephthys', '奈芙蒂斯的叙事者', 'ネフティスの語り手', 'Effect Monster', 'Spellcaster', 'WIND', 2, 300, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：以「奈芙提斯之叙述者」以外的自己墓地1张「奈芙提斯」卡为对象才能发动。选1张手卡破坏，作为对象的卡加入手卡。 ②：这张卡被效果破坏送去墓地的场合，下次的自己准备阶段才能发动。从自己墓地选「奈芙提斯之叙述者」以外的1张「奈芙提斯」卡加入手卡。'),
(12289247, 'Chronograph Sorcerer', '刻读阵魔术士', 'クロノグラフ・マジシャン', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 6, 2000, 1700, '①：自己场上的卡被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从手卡把1只怪兽特殊召唤。 ②：把自己的手卡·场上·墓地的「灵摆龙」「超量龙」「同调龙」「融合龙」怪兽各1只和场上的这张卡除外才能发动。把1只「霸王龙 扎克」当作融合召唤从额外卡组特殊召唤。'),
(24506253, 'Chronomaly Acambaro Figures', '先史遗产 阿坎巴罗土偶', '先史遺産アカンバロの土偶', 'Effect Monster', 'Rock', 'EARTH', 5, 1000, 1800, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的「先史遗产」怪兽被战斗或者对方的效果破坏的场合，可以作为代替把手卡的这张卡丢弃。 ②：这张卡在墓地存在的场合，支付1000基本分才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡在结束阶段回到持有者手卡。这个效果发动的回合，自己不是「先史遗产」怪兽不能特殊召唤。'),
(94766498, 'Chronomaly Aztec Mask Golem', '先史遗产 阿兹特克面具石人', '先史遺産アステカ・マスク・ゴーレム', 'Effect Monster', 'Rock', 'EARTH', 4, 1500, 1000, '自己回合自己是有把名字带有「先史遗产」的魔法卡发动的场合，这张卡可以从手卡特殊召唤。「先史遗产 阿兹特克面具石人」在自己场上只能有1只表侧表示存在。'),
(20154092, 'Chronomaly Cabrera Trebuchet', '先史遗产 卡布雷拉投石机', '先史遺産カブレラの投石機', 'Effect Monster', 'Rock', 'EARTH', 4, NULL, 1800, '1回合1次，把这张卡以外的自己场上1只名字带有「先史遗产」的怪兽解放，选择对方场上表侧表示存在的1只怪兽才能发动。选择的怪兽的攻击力直到结束阶段时变成0。'),
(4357063, 'Chronomaly City Babylon', '先史遗产都市 巴比伦', '先史遺産都市バビロン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '1回合1次，把自己墓地1只名字带有「先史遗产」的怪兽从游戏中除外，从自己墓地选择持有和除外的怪兽相同等级的1只名字带有「先史遗产」的怪兽才能发动。选择的怪兽特殊召唤。'),
(52158283, 'Chronomaly Colossal Head', '先史遗产 巨石人头像', '先史遺産コロッサル・ヘッド', 'Effect Monster', 'Rock', 'EARTH', 4, 800, 1600, '把墓地的这张卡从游戏中除外，选择场上攻击表示存在的1只3星以上的怪兽才能发动。选择的怪兽变成表侧守备表示或者里侧守备表示。「先史遗产 巨石人头像」的效果1回合只能使用1次。'),
(15941690, 'Chronomaly Crystal Bones', '先史遗产 水晶骨架', '先史遺産クリスタル・ボーン', 'Effect Monster', 'Rock', 'LIGHT', 3, 1300, 400, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功时，可以从自己的手卡·墓地选「先史遗产 水晶骨架」以外的1只名字带有「先史遗产」的怪兽特殊召唤。'),
(93730230, 'Chronomaly Crystal Chrononaut', '先史遗产 水晶外星人', '先史遺産クリスタル・エイリアン', 'XYZ Monster', 'Psychic', 'LIGHT', 3, 2100, 1000, '3星怪兽×2 1回合1次，这张卡被选择作为攻击对象时，把这张卡1个超量素材取除才能发动。这个回合，这张卡不会被战斗以及卡的效果破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。'),
(51435705, 'Chronomaly Crystal Skull', '先史遗产 水晶头骨', '先史遺産クリスタル・スカル', 'Effect Monster', 'Rock', 'LIGHT', 3, 900, 600, '这个卡名的效果1回合只能使用1次。 ①：自己场上有「先史遗产」怪兽存在的场合，把这张卡从手卡丢弃去墓地才能发动。从自己的卡组·墓地选「先史遗产 水晶头骨」以外的1只「先史遗产」怪兽加入手卡。'),
(50797682, 'Chronomaly Esperanza Glyph', '先史遗产石纹', '先史遺産石紋', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，以自己的场上·墓地1张超量怪兽卡为对象才能发动。从自己的手卡·卡组·墓地选持有比那张怪兽卡的阶级数值高1的等级的2只「先史遗产」怪兽效果无效特殊召唤，只用那2只为素材把1只「先史遗产」超量怪兽超量召唤。'),
(88552992, 'Chronomaly Golden Jet', '先史遗产 黄金航天飞机', '先史遺産ゴールデン・シャトル', 'Effect Monster', 'Machine', 'LIGHT', 4, 1300, 1400, '1回合1次，自己的主要阶段时才能发动。自己场上的全部名字带有「先史遗产」的怪兽的等级上升1星。'),
(72837335, 'Chronomaly Gordian Knot', '先史遗产 戈耳狄俄斯结合体', '先史遺産ゴルディアス・ユナイト', 'Effect Monster', 'Rock', 'EARTH', 3, 300, 900, '这张卡召唤成功时，可以从手卡把1只名字带有「先史遗产」的怪兽特殊召唤。这张卡的等级变成和这个效果特殊召唤的怪兽的等级相同。'),
(97112505, 'Chronomaly Magella Globe', '先史遗产 墨瓦腊地球仪', '先史遺産メガラ・グローヴ', 'Effect Monster', 'Machine', 'LIGHT', 4, 1500, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。从卡组把「先史遗产 墨瓦腊地球仪」以外的1只「先史遗产」怪兽特殊召唤。 ②：这张卡在墓地存在的场合，从自己墓地把「先史遗产 墨瓦腊地球仪」以外的1张「先史遗产」卡除外才能发动。这张卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(25163248, 'Chronomaly Mayan Machine', '先史遗产 玛雅机器', '先史遺産マヤン・マシーン', 'Effect Monster', 'Machine', 'EARTH', 3, 1500, 700, '机械族怪兽上级召唤的场合，这张卡可以作为2只的数量解放。'),
(87430304, 'Chronomaly Moai', '先史遗产 摩艾石像', '先史遺産モアイ', 'Effect Monster', 'Rock', 'EARTH', 5, 1800, 1600, '自己场上有名字带有「先史遗产」的怪兽存在的场合，这张卡可以从手卡表侧守备表示特殊召唤。'),
(38007744, 'Chronomaly Moai Carrier', '先史遗产 摩艾石像搬运器', '先史遺産モアイキャリア', 'Effect Monster', 'Rock', 'EARTH', 5, 900, 1800, '对方场上有卡存在，自己场上没有卡存在的场合，这张卡可以从手卡特殊召唤。'),
(67559101, 'Chronomaly Mud Golem', '先史遗产 泥土人偶·遮光器', '先史遺産マッドゴーレム・シャコウキ', 'Effect Monster', 'Rock', 'EARTH', 4, 1700, 1000, '只要这张卡在场上表侧表示存在，自己场上的名字带有「先史遗产」的怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(24861088, 'Chronomaly Nebra Disk', '先史遗产 内布拉星象盘', '先史遺産ネブラ・ディスク', 'Effect Monster', 'Machine', 'LIGHT', 4, 1800, 1500, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤成功时才能发动。从卡组把「先史遗产 内布拉星象盘」以外的1张「先史遗产」卡加入手卡。 ②：这张卡在墓地存在，自己场上的怪兽只有「先史遗产」怪兽的场合才能发动。这张卡守备表示特殊召唤。这个效果发动的回合，自己不能把「先史遗产」卡以外的卡的效果发动。'),
(26345570, 'Chronomaly Pyramid Eye Tablet', '先史遗产-金字塔眼板', '先史遺産－ピラミッド・アイ・タブレット', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上的名字带有「先史遗产」的怪兽的攻击力上升800。'),
(93543806, 'Chronomaly Sol Monolith', '先史遗产 太阳独石碑', '先史遺産ソル・モノリス', 'Effect Monster', 'Rock', 'EARTH', 6, 600, 600, '1回合1次，选择自己场上1只名字带有「先史遗产」的怪兽才能发动。选择的怪兽的等级变成6星。这个效果发动的回合，自己不能把名字带有「先史遗产」的怪兽以外的怪兽特殊召唤。'),
(90951921, 'Chronomaly Technology', '先史遗产技术', '先史遺産技術', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地1只名字带有「先史遗产」的怪兽才能发动。选择的怪兽从游戏中除外。那之后，从自己卡组上面把2张卡确认，从那之中选1张加入手卡，剩下的卡送去墓地。「先史遗产技术」在1回合只能发动1张，这张卡发动的回合自己不能把名字带有「先史遗产」的怪兽以外的怪兽特殊召唤。'),
(98204536, 'Chronomaly Temple - Trilithon', '先史遗产惊神殿-三巨石', '先史遺産驚神殿－トリリトン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的怪兽不存在的场合或者只有「先史遗产」怪兽的场合，支付500基本分才能发动。从手卡把1只「先史遗产」怪兽召唤。 ②：自己的「先史遗产」超量怪兽或者自己的「No.」超量怪兽把超量素材取除来让效果发动的场合，可以作为取除的1个超量素材的代替而把这张卡送去墓地。'),
(5291803, 'Chronomaly Tula Guardian', '先史遗产 图拉守护者', '先史遺産トゥーラ・ガーディアン', 'Effect Monster', 'Rock', 'EARTH', 5, 1800, 900, '场地魔法卡表侧表示存在的场合，这张卡可以从手卡特殊召唤。「先史遗产 图拉守护者」在自己场上只能有1只表侧表示存在。'),
(2089016, 'Chronomaly Tuspa Rocket', '先史遗产 图什帕火箭', '先史遺産トゥスパ・ロケット', 'Effect Monster', 'Rock', 'EARTH', 4, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，从卡组·额外卡组把1只「先史遗产」怪兽送去墓地，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降送去墓地的怪兽的等级或者阶级×200。 ②：场上的这张卡为素材作超量召唤的「No.」怪兽得到以下效果。 ●这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(2609443, 'Chronomaly Vimana', '先史遗产 维摩那', '先史遺産ヴィマナ', 'XYZ Monster', 'Machine', 'LIGHT', 5, 2300, 2600, '5星怪兽×2 ①：自己·对方回合1次，以场上1只表侧表示怪兽和自己墓地1只「先史遗产」怪兽或超量怪兽为对象才能发动。那只场上的怪兽的攻击力直到回合结束时上升作为对象的墓地的怪兽的攻击力一半数值。那之后，把作为对象的墓地的怪兽作为这张卡的超量素材。 ②：1回合1次，对方把怪兽的效果发动时，把这张卡2个超量素材取除才能发动。那个发动无效。'),
(65591858, 'Chronomaly Winged Sphinx', '先史遗产 飞翼斯芬克斯像', '先史遺産ウィングス・スフィンクス', 'Effect Monster', 'Rock', 'EARTH', 5, 1600, 1900, '这张卡召唤成功时，可以从自己墓地选择1只名字带有「先史遗产」的5星怪兽特殊召唤。这个效果发动的回合，自己不能把名字带有「先史遗产」的怪兽以外的怪兽特殊召唤。'),
(17363041, 'Chrysalis Chicky', '茧状体·小雏鸟', 'C・チッキー', 'Effect Monster', 'Winged Beast', 'WIND', 2, 600, 400, '场上有「新宇宙」存在时，可以把这张卡作为祭品从手卡·卡组特殊召唤1只「新空间侠·天空蜂鸟」。'),
(42682609, 'Chrysalis Dolphin', '茧状体·小海豚', 'C・ドルフィーナ', 'Effect Monster', 'Fish', 'WATER', 2, 400, 600, '场上有「新宇宙」存在时，可以把这张卡作为祭品，从手卡·卡组特殊召唤1只「新空间侠·水波海豚」。'),
(16241441, 'Chrysalis Larva', '茧状体·小幼虫', 'C・ラーバ', 'Effect Monster', 'Insect', 'FIRE', 2, 300, 300, '场上有「新宇宙」存在时，可以把这张卡作为祭品从手卡·卡组特殊召唤1只「新空间侠·火焰甲虫」。'),
(42239546, 'Chrysalis Mole', '茧状体·小鼹鼠', 'C・モーグ', 'Effect Monster', 'Rock', 'EARTH', 2, 700, 100, '场上有「新宇宙」存在时，可以把这张卡作为祭品从手卡·卡组特殊召唤1只「新空间侠·大地鼹鼠」。'),
(43751755, 'Chrysalis Pantail', '茧状体·小黑豹', 'C・パンテール', 'Effect Monster', 'Beast', 'DARK', 2, 800, 300, '场上有「新宇宙」存在时，可以把这张卡作为祭品从手卡·卡组特殊召唤1只「新空间侠·黑暗豹」。'),
(29246354, 'Chrysalis Pinny', '茧状体·小松茸', 'C・ピニー', 'Effect Monster', 'Plant', 'LIGHT', 2, 100, 700, '场上有「新宇宙」存在时，可以把这张卡作为祭品从手卡·卡组特殊召唤1只「新空间侠·光辉青苔」。'),
(46910446, 'Chthonian Alliance', '地狱联盟', 'ヘル・アライアンス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '场上每有1只表侧表示存在的和装备怪兽同名的怪兽，装备怪兽攻击力上升800。'),
(18271561, 'Chthonian Blast', '地狱爆破', 'ヘル・ブラスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的怪兽破坏送去墓地时发动。场上表侧表示攻击力最低的1只怪兽破坏，双方受到那个攻击力一半的数值的伤害。'),
(95888876, 'Chthonian Emperor Dragon', '地狱帝王龙', 'ヘルカイザー・ドラゴン', 'Gemini Monster', 'Dragon', 'FIRE', 6, 2400, 1500, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●这张卡在同1次的战斗阶段中可以作2次攻击。'),
(72287557, 'Chthonian Polymer', '地狱聚合体', 'ヘル・ポリマー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的融合怪兽融合召唤时发动。把自己场上1只怪兽作为祭品，得到那1只融合怪兽的控制权。'),
(50916353, 'Chthonian Soldier', '地狱战士', '地獄戦士', 'Effect Monster', 'Warrior', 'DARK', 4, 1200, 1400, '这张卡因对方怪兽的攻击破坏送去墓地时，也给与对方基本分这次战斗让自己受到的战斗伤害。'),
(8508055, 'Chu-Ske the Mouse Fighter', '格斗鼠 吱助', '格闘ねずみ チュー助', 'Normal Monster', 'Beast', 'EARTH', 3, 1200, NULL, '目标是成为鼠界最强的格斗家而在世界范围内流浪的热血鼠。无知的触碰它会很受伤哦。'),
(29092121, 'Cipher Biplane', '光波复叶机', '光波複葉機', 'Effect Monster', 'Machine', 'LIGHT', 6, 1000, 2000, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有「光波」怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，以自己场上2只「光波」怪兽为对象才能发动。那些怪兽的等级直到回合结束时变成8星。 ③：这张卡被战斗·效果破坏送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只「光波」怪兽加入手卡。'),
(99397762, 'Cipher Bit', '光波防轮', '光波防輪', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「银河眼」超量怪兽或者「光波」超量怪兽为对象才能发动。把这张卡在那只怪兽下面重叠作为超量素材，那只怪兽在这个回合只有1次不会被战斗·效果破坏。'),
(79094383, 'Cipher Etranger', '光波异邦臣', '光波異邦臣', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡在手卡·墓地存在的场合，以自己场上1只「光波」超量怪兽为对象才能发动。把这张卡在那只怪兽下面重叠作为超量素材。 ②：这张卡被送去墓地的场合才能发动。从卡组把1张「光波」魔法·陷阱卡加入手卡。'),
(55496220, 'Cipher Interference', '光波干涉', '光波干渉', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：场上有同名怪兽存在的自己的「光波」怪兽进行战斗的伤害计算时才能发动。那只进行战斗的自己的「光波」怪兽的攻击力直到战斗阶段结束时变成2倍。'),
(58383100, 'Cipher Mirror Knight', '光波镜骑士', '光波鏡騎士', 'Effect Monster', 'Warrior', 'LIGHT', 4, NULL, NULL, '「光波镜骑士」的②的效果1回合只能使用1次。 ①：自己的「光波」怪兽1只被战斗破坏送去自己墓地时，把这张卡从手卡丢弃才能发动。选自己的手卡·场上1张卡送去墓地，那只破坏的怪兽特殊召唤。 ②：这张卡被送去墓地的回合的结束阶段才能发动。从卡组把1张「光波」卡加入手卡。'),
(79853073, 'Cipher Soldier', '密码侦察者', 'サイファー・スカウター', 'Effect Monster', 'Machine', 'EARTH', 3, 1350, 1800, '这张卡和战士族怪兽进行战斗的伤害计算时发动。这张卡的攻击力·守备力只在那次伤害计算时上升2000。'),
(98905, 'Cipher Spectrum', '光波分光', '光波分光', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的持有超量素材的「光波」超量怪兽被战斗或者对方的效果破坏送去自己墓地的场合，以那1只怪兽为对象才能发动。那只怪兽从墓地特殊召唤，把1只和那只怪兽同名的超量怪兽从额外卡组特殊召唤。'),
(21999001, 'Cipher Twin Raptor', '光波双颚机', '光波双顎機', 'Effect Monster', 'Machine', 'LIGHT', 4, 1600, 800, '这个卡名的②的效果1回合只能使用1次。 ①：从额外卡组特殊召唤的怪兽在对方场上存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：丢弃1张手卡才能发动。从手卡·卡组把1只「光波」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是「光波」怪兽不能特殊召唤。'),
(81974607, 'Cipher Wing', '光波翼机', '光波翼機', 'Effect Monster', 'Machine', 'LIGHT', 4, 1400, 1200, '①：自己场上有「光波」怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡解放才能发动。自己场上的全部「光波」怪兽的等级直到回合结束时上升4星。'),
(57143342, 'Cir, Malebranche of the Burning Abyss', '彼岸恶鬼 加特霍格', '彼岸の悪鬼 ガトルホッグ', 'Effect Monster', 'Fiend', 'DARK', 3, 1600, 1200, '这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。 ③：这张卡被送去墓地的场合，以「彼岸的恶鬼 齐里亚托」以外的自己墓地1只「彼岸」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(12954226, 'Circle of the Fairies', '妖精圆环', 'サークル・オブ・フェアリー', 'Synchro Monster', 'Plant', 'WIND', 7, 2200, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只昆虫族·植物族怪兽召唤。 ②：自己的昆虫族·植物族怪兽的战斗让怪兽被破坏送去墓地时，以那1只破坏的怪兽为对象才能发动。给与对方那只怪兽的攻击力一半数值的伤害。那之后，自己基本分回复给与的伤害的数值。'),
(59388357, 'Circle of the Fire Kings', '炎王炎环', '炎王炎環', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只炎属性怪兽和自己墓地1只炎属性怪兽为对象才能发动。作为对象的自己场上的怪兽破坏，作为对象的墓地的怪兽特殊召唤。'),
(46290741, 'Citadel Whale', '城塞鲸', '城塞クジラ', 'Effect Monster', 'Fish', 'WATER', 7, 2350, 2150, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，把自己场上2只水属性怪兽解放才能发动。这张卡特殊召唤。 ②：这张卡特殊召唤成功的场合才能发动。从卡组选1张「潜海奇袭」在自己场上盖放。 ③：1回合1次，只以自己场上的水属性怪兽1只为对象的魔法·陷阱·怪兽的效果由对方发动时才能发动。那个发动无效并破坏。'),
(1482001, 'Clara & Rushka, the Ventriloduo', '副话术士克拉拉＆露西卡', '副話術士クララ＆ルーシカ', 'Link Monster', 'Spellcaster', 'EARTH', NULL, NULL, NULL, '通常召唤的怪兽1只 这张卡的连接召唤不在主要阶段2不能进行。'),
(57496978, 'Clashing Souls', '互相碰撞的灵魂', 'ぶつかり合う魂', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己的攻击表示怪兽和持有比自身的攻击力高的攻击力的对方的攻击表示怪兽进行战斗的伤害计算时才能发动。那些进行战斗的怪兽之内攻击力低的怪兽的控制者可以支付500基本分让那只怪兽的攻击力只在伤害计算时上升500。那之后，直到变成双方不支付基本分为止让这个效果重复。那次战斗发生的双方的战斗伤害变成0，伤害计算后那次战斗让怪兽被破坏的玩家的场上的卡全部送去墓地。'),
(98234196, 'Clavkiys, the Magikey Skyblaster', '魔键铳士-克莱维斯', '魔鍵銃士－クラヴィス', 'Normal Monster', 'Warrior', 'DARK', 4, 1900, 1900, '每个人都充满可能性。要走还是要停，施锁还是解锁，皆是取决于自己。目眩神迷的世界有许多门扉。为其解锁的是魔法钥匙。2把钥匙1扇大门。2个意志1个身姿。大门若是解锁，世界就会相连，巨大的力量从中显现。'),
(41218256, 'Claw Reacher', '利爪杀手', 'キラー・ザ・クロー', 'Normal Monster', 'Fiend', 'DARK', 3, 1000, 800, '手腕能自由的伸缩，尖利的爪子能将敌人刺穿。'),
(22479888, 'Clay Charge', '黏土冲撞', 'クレイ・チャージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的「元素英雄 黏土侠」被选择为攻击对象时才能发动（若选择的卡是里侧守备表示的场合，那张卡需要确认）。攻击怪兽和选择的「元素英雄 黏土侠」破坏，给与对方基本分800分的伤害。'),
(33506331, 'Clear Cube', '清透立方体', 'クリアー・キューブ', 'Effect Monster', 'Machine', 'DARK', 1, NULL, NULL, '①：只要这张卡在怪兽区域存在，「清透世界」的效果对自己不适用。 ②：自己在通常召唤外加上只有1次，自己主要阶段可以把有「清透世界」的卡名记述的1只怪兽召唤。 ③：表侧表示的这张卡因对方从场上离开的场合才能发动。从卡组把有「清透世界」的卡名记述的1只怪兽特殊召唤。'),
(58518520, 'Clear Effector', '澄净效应者', 'クリア・エフェクター', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, NULL, 900, '①：这张卡作为同调素材送去墓地的场合发动。自己从卡组抽1张。 ②：这张卡为同调素材的同调怪兽不会被效果破坏。'),
(46613515, 'Clear Kuriboh', '洁净栗子球', 'クリアクリボー', 'Effect Monster', 'Fairy', 'LIGHT', 1, 300, 200, '这个卡名的②的效果1回合只能使用1次。 ①：给与伤害的怪兽的效果由对方发动时，把这张卡从手卡丢弃才能发动。那个发动无效。 ②：对方怪兽的直接攻击宣言时，把墓地的这张卡除外才能发动。自己从卡组抽1张。那张抽到的卡是怪兽的场合，可以再把那只怪兽特殊召唤。那之后，攻击对象转移为那只怪兽。'),
(21570001, 'Clear New World', '新世坏界', '新世壊', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏，和那只怪兽是原本的种族·属性不同并持有比那只怪兽的原本等级低的等级的1只怪兽从卡组守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(70717628, 'Clear Phantom', '清透幻影', 'クリアー・ファントム', 'Effect Monster', 'Fiend', 'DARK', 3, 1200, 800, '这个卡名的①的效果1回合只能使用1次。 ①：把包含这张卡的2张手卡丢弃才能发动。把「清透世界」或者有那个卡名记述的魔法·陷阱卡合计2张从卡组加入手卡。 ②：只要这张卡在怪兽区域存在，「清透世界」的效果对自己不适用。 ③：这张卡被破坏的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏，从对方卡组上面把3张卡送去墓地。'),
(7102732, 'Clear Rage Golem', '清透狂怒石人', 'クリアー・レイジ・ゴーレム', 'Effect Monster', 'Rock', 'DARK', 4, 1600, 1800, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。这个回合中，有「清透世界」的卡名记述的自己怪兽可以直接攻击。 ②：只要这张卡在怪兽区域存在，「清透世界」的效果对自己不适用。 ③：这张卡给与对方战斗伤害时才能发动。给与对方为对方手卡数量×300伤害。'),
(97811903, 'Clear Vice Dragon', '清透恶龙', 'クリアー・バイス・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 8, -1, NULL, '①：只要这张卡在怪兽区域存在，「清透世界」的效果对自己不适用。 ②：这张卡的攻击力只在向对方怪兽攻击的伤害计算时变成那只对方怪兽的攻击力的2倍。 ③：场上的这张卡被对方的效果破坏的场合，可以作为代替把自己1张手卡丢弃。'),
(70095046, 'Clear Vicious Knight', '清透堕恶骑士', 'クリアー・ヴィシャス・ナイト', 'Effect Monster', 'Warrior', 'DARK', 7, 2300, 1100, '这张卡可以把有「清透世界」的卡名记述的1只怪兽解放作上级召唤。 ①：这张卡的攻击力上升对方场上的怪兽的最高原本攻击力数值。 ②：只要这张卡在怪兽区域存在，「清透世界」的效果对自己不适用。 ③：只要上级召唤的这张卡在怪兽区域存在，对方不能把持有比这张卡低的攻击力的场上的特殊召唤的怪兽的效果发动。'),
(6089145, 'Clear Wall', '清透壁', 'クリアー・ウォール', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：场上有「清透世界」存在的场合才能发动。从卡组把有「清透世界」的卡名记述的1只怪兽加入手卡。 ②：有「清透世界」的卡名记述的怪兽不会被战斗破坏，那次战斗发生的对自己的战斗伤害变成0。 ③：只要有「清透世界」的卡名记述的7星以上的怪兽在自己场上存在，「清透世界」的效果不论属性而全部对对方适用。'),
(90036274, 'Clear Wing Fast Dragon', '清透翼疾速龙', 'クリアウィング・ファスト・ドラゴン', 'Synchro Pendulum Effect Monster', 'Dragon', 'WIND', 7, 2500, 2000, '调整＋调整以外的风属性怪兽1只以上 「幻透翼疾速龙」的①的怪兽效果1回合只能使用1次。 ①：以从额外卡组特殊召唤的对方场上1只表侧表示怪兽为对象才能发动。直到回合结束时，那只怪兽的攻击力变成0，效果无效化。这个效果在对方回合也能发动。 ②：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(82044280, 'Clear Wing Synchro Dragon', '清透翼同步龙', 'クリアウィング・シンクロ・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 7, 2500, 2000, NULL),
(33900648, 'Clear World', '清透世界', 'クリアー・ワールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己结束阶段支付500基本分或把这张卡破坏。 ①：双方让自身场上的怪兽属性的以下效果对自身适用。 ●光：手卡全部持续公开。 ●暗：自己场上的怪兽是2只以上的场合，不能攻击宣言。 ●地：自己准备阶段把自己1只表侧守备表示怪兽破坏。 ●水：自己结束阶段选1张手卡丢弃。 ●炎：自己结束阶段受到1000伤害。 ●风：若不支付500基本分则不能把魔法卡发动。'),
(45778242, 'Cliant', '克莱因客户端蚁', 'クラインアント', 'Effect Monster', 'Cyberse', 'LIGHT', 3, 1500, 1500, '①：只要通常召唤的这张卡在怪兽区域存在，自己场上的电子界族怪兽的攻击力·守备力在自己回合内上升500。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替把自己的手卡·场上1只电子界族怪兽破坏。'),
(2992467, 'Click & Echo', '咔啵＆回啵', 'クリック＆エコー', 'Effect Monster', 'Sea Serpent', 'WATER', 2, 300, 2100, '这张卡不能作为融合·同调·超量召唤的素材。这个卡名的②的效果1回合可以使用最多2次。 ①：只要这张卡在怪兽区域存在，这张卡不能解放。 ②：这张卡作为连接素材送去墓地的场合发动。这张卡在从那个连接召唤的玩家来看的对方场上守备表示特殊召唤。 ③：只要这张卡的②的效果特殊召唤的这张卡在怪兽区域存在，自己把手卡持续公开。'),
(8323633, 'Cloak and Dagger', '夜雾的狙击手', '夜霧のスナイパー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '宣言1个怪兽卡名。对方把宣言怪兽召唤·特殊召唤·反转的场合，宣言怪兽和这张卡从游戏中除外。'),
(87468732, 'Clock Arc', '变导机咎 弧线钟摆机', '変導機咎 クロックアーク', 'Pendulum Effect Monster', 'Machine', 'DARK', 4, 600, 1200, '①：这张卡往中央以外的主要怪兽区域特殊召唤的场合破坏。 ②：这张卡不会被战斗破坏。 ③：对方结束阶段，以自己的灵摆区域1张卡为对象才能发动。那张卡破坏，这张卡在自己的灵摆区域放置。'),
(51476410, 'Clock Lizard', '时脉蜥蜴', 'クロック・リザード', 'Link Monster', 'Cyberse', 'DARK', NULL, 1200, NULL, '电子界族怪兽2只 ①：把这张卡解放才能发动。从自己墓地选1只融合怪兽回到额外卡组。那之后，那张融合怪兽卡决定的融合素材怪兽从自己墓地除外，把那1只融合怪兽从额外卡组融合召唤。 ②：墓地的这张卡被除外的场合才能发动。对方场上的特殊召唤的怪兽的攻击力直到回合结束时下降自己墓地的电子界族怪兽数量×400。'),
(77087109, 'Clock Resonator', '时钟共鸣者', 'クロック・リゾネーター', 'Tuner Monster', 'Fiend', 'EARTH', 3, 1200, 600, '只要这张卡在场上表侧守备表示存在，这张卡1回合只有1次不会被战斗或者卡的效果破坏。'),
(4478086, 'Clock Spartoi', '时脉地生人', 'クロック・スパルトイ', 'Link Monster', 'Cyberse', 'DARK', NULL, 800, NULL, '电子界族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「电脑网融合」加入手卡。 ②：这张卡所连接区有怪兽特殊召唤的场合，以自己墓地1只4星以下的电子界族怪兽为对象才能发动。那只怪兽效果无效特殊召唤。这个效果的发动后，直到回合结束时自己不是融合怪兽不能从额外卡组特殊召唤。'),
(75041269, 'Clock Tower Prison', '幽狱时钟塔', '幽獄の時計塔', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '对方回合的准备阶段时，这张卡放置1个时计指示物。时计指示物合计有4个以上的场合，这张卡的控制者不会受到战斗伤害。放置有4个以上时计指示物的这张卡被破坏送去墓地时，从手卡·卡组特殊召唤1只「命运英雄 恐惧人」。'),
(21830679, 'Clock Wyvern', '时脉飞龙', 'クロック・ワイバーン', 'Effect Monster', 'Cyberse', 'WIND', 4, 1800, 1000, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。这张卡的攻击力变成一半，在自己场上把1只「时钟衍生物」（电子界族·风·1星·攻/守0）特殊召唤。'),
(41739381, 'Clockwork Knight', '机械装置作响骑士', '機械仕掛けの騎士', 'Link Monster', 'Machine', 'EARTH', NULL, 500, NULL, '连接怪兽以外的原本攻击力是1000以下的机械族怪兽1只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合，把自己场上1张表侧表示的永续魔法卡送去墓地才能发动。从卡组把1张「机械驱动之夜」加入手卡。 ②：以自己墓地1只攻击力1000以下的机械族怪兽为对象才能发动。自己场上1只其他的机械族怪兽解放，作为对象的怪兽守备表示特殊召唤。'),
(84797028, 'Clockwork Night', '机械装置作响之夜', '機械仕掛けの夜－クロック・ワーク・ナイト－', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：场上的表侧表示怪兽变成机械族。 ②：自己场上的机械族怪兽的攻击力·守备力上升500，对方场上的机械族怪兽的攻击力·守备力下降500。 ③：把墓地的这张卡除外，丢弃1张手卡才能发动。从卡组把1只机械族·地属性怪兽加入手卡。'),
(86871615, 'Clone Token', '克隆复制', 'クローン複製', 'Token', 'Warrior', NULL, NULL, NULL, NULL, NULL),
(86871614, 'Cloning', '克隆复制', 'クローン複製', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方对怪兽的召唤·反转召唤成功时，以那1只怪兽为对象才能发动。把持有那只表侧表示怪兽的原本的种族·属性·等级·攻击力·守备力的1只「克隆衍生物」在自己场上特殊召唤。那只表侧表示怪兽被破坏送去墓地时这衍生物破坏。'),
(22723778, 'Clorless, Chaos King of Dark World', '暗黑界的混沌王 卡勒莱斯', '暗黒界の混沌王 カラレス', 'Fusion Monster', 'Fiend', 'DARK', 12, -1, -1, '「暗黑界的魔神 雷恩」＋恶魔族怪兽2只以上 ①：这张卡融合召唤的场合才能发动。对方场上的卡全部破坏。 ②：这张卡的原本的攻击力·守备力变成作为这张卡的融合素材的怪兽数量×1000。 ③：自己·对方回合1次，以自己场上1张表侧表示卡为对象才能发动。选自己1张手卡丢弃。这个回合，对方不能把作为对象的表侧表示卡作为效果的对象。'),
(78082039, 'Closed Forest', '封闭的森林', 'クローザー・フォレスト', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '自己墓地存在的怪兽每有1只，自己场上表侧表示存在的兽族怪兽的攻击力上升100。只要这张卡在场上存在，不能把场地魔法卡发动。此外，这张卡被破坏的回合，不能把场地魔法卡发动。'),
(9348522, 'Cloudcastle', '浮鵺城', '浮鵺城', 'Synchro Monster', 'Machine', 'WIND', 9, NULL, 3000, '调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤成功时，以自己墓地1只9星怪兽为对象才能发动。那只怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，召唤·特殊召唤的8星以下的怪兽在那个回合不能攻击。'),
(17810268, 'Cloudian - Acid Cloud', '云魔物-酸云', '雲魔物－アシッド・クラウド', 'Effect Monster', 'Fairy', 'WATER', 4, 500, NULL, '这张卡不会被战斗破坏。这张卡表侧守备表示在场上存在的场合，这张卡破坏。这张卡的召唤成功时，给这张卡放置场上存在的名字带有「云魔物」的怪兽数量的雾指示物。可以把这张卡放置的雾指示物取除2个，场上1张魔法或者陷阱卡破坏。'),
(79703905, 'Cloudian - Altus', '云魔物-高层云', '雲魔物－アルトス', 'Effect Monster', 'Fairy', 'WATER', 4, 1300, NULL, '这张卡不会被战斗破坏。这张卡表侧守备表示在场上存在的场合，这张卡破坏。这张卡的召唤成功时，给这张卡放置场上存在的名字带有「云魔物」的怪兽数量的雾指示物。可以把场上存在的雾指示物取除3个，对方手卡随机丢弃1张。'),
(43318266, 'Cloudian - Cirrostratus', '云魔物-卷层云', '雲魔物－キロスタス', 'Effect Monster', 'Fairy', 'WATER', 4, 900, NULL, '这张卡不会被战斗破坏。这张卡表侧守备表示在场上存在的场合，这张卡破坏。这张卡的召唤成功时，给这张卡放置场上存在的名字带有「云魔物」的怪兽数量的雾指示物。可以把这张卡放置的雾指示物取除2个，场上1只怪兽破坏。'),
(57610714, 'Cloudian - Eye of the Typhoon', '云魔物-台风眼', '雲魔物－アイ・オブ・ザ・タイフーン', 'Effect Monster', 'Aqua', 'WIND', 8, 3000, 1000, '这张卡不会被战斗破坏。这张卡表侧守备表示在场上存在的场合，这张卡破坏。这张卡的攻击宣言时，把名字带有「云魔物」的卡以外的全部表侧表示怪兽的表示形式改变。'),
(83604828, 'Cloudian - Ghost Fog', '云魔物-鬼雾', '雲魔物－ゴースト・フォッグ', 'Effect Monster', 'Fiend', 'WATER', 1, NULL, NULL, '这张卡不能特殊召唤。这张卡的战斗发生的对双方玩家的战斗伤害变成0。这张卡被战斗破坏的场合，给场上表侧表示存在的怪兽放置让这张卡破坏的怪兽的等级数量的雾指示物。'),
(20003527, 'Cloudian - Nimbusman', '云魔物-雨云人', '雲魔物－ニンバスマン', 'Effect Monster', 'Fairy', 'WATER', 5, 1000, 1000, '这张卡不会被战斗破坏。这张卡表侧守备表示在场上存在的场合，这张卡破坏。这张卡祭品召唤的场合，可以只用自己场上任意数量的水属性怪兽作为祭品。这张卡的祭品召唤成功时，给这张卡放置作为祭品的水属性怪兽数量的雾指示物。这张卡的攻击力每有1个雾指示物上升500。'),
(83982270, 'Cloudian - Poison Cloud', '云魔物-毒云', '雲魔物－ポイズン・クラウド', 'Effect Monster', 'Fiend', 'WATER', 3, NULL, 1000, '场上表侧表示存在的这张卡被战斗破坏送去墓地时，把让这张卡破坏的怪兽破坏并给与对方基本分800分伤害。'),
(56597272, 'Cloudian - Sheep Cloud', '云魔物-羊云', '雲魔物－羊雲', 'Effect Monster', 'Fairy', 'WATER', 1, NULL, NULL, '这张卡被战斗破坏送去墓地时，在自己场上把2只「云魔物衍生物」（天使族·水·1星·攻/守0）守备表示特殊召唤。这些衍生物不能作为名字带有「云魔物」的卡以外的祭品召唤的祭品。'),
(80825553, 'Cloudian - Smoke Ball', '云魔物-小烟球', '雲魔物－スモークボール', 'Normal Monster', 'Fairy', 'WATER', 1, 200, 600, '云魔物的小小云孩。特别讨厌一个人孤零零，特别喜欢和同伴们乘着微风摇摇晃晃到处散步。'),
(13474291, 'Cloudian - Storm Dragon', '云魔物-风暴龙', '雲魔物－ストーム・ドラゴン', 'Effect Monster', 'Fairy', 'WATER', 4, 1000, NULL, '这张卡不能通常召唤。把自己墓地1只名字带有「云魔物」的怪兽从游戏中除外特殊召唤。这张卡不会被战斗破坏。这张卡表侧守备示在场上存在的场合，这张卡破坏。1回合只有1次，可以给场上1只怪兽放置1个雾指示物。'),
(16197610, 'Cloudian - Turbulence', '云魔物-乱气流', '雲魔物－タービュランス', 'Effect Monster', 'Fairy', 'WATER', 4, 800, NULL, '这张卡不会被战斗破坏。这张卡在场上表侧守备表示存在的场合，这张卡破坏。这张卡召唤成功时，场上的名字带有「云魔物」的怪兽数量的雾指示物给这张卡放置。此外，可以通过把这张卡放置的1个雾指示物取除，从自己卡组或者双方墓地选1只「云魔物-小烟球」特殊召唤。'),
(88210105, 'Cloudian Aerosol', '云魔物的云核', '雲魔物の雲核', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从手卡丢弃1只「云魔物」怪兽，以场上1只表侧表示怪兽为对象才能发动。给作为对象的怪兽放置那自身等级数量的雾指示物。 ②：从自己墓地把这张卡和1只「云魔物」怪兽除外才能发动。从卡组把1只「云魔物」怪兽特殊召唤。');